suppressPackageStartupMessages(library(openxlsx))
args<-commandArgs(trailingOnly=FALSE);f<-sub('^--file=','',args[grepl('^--file=',args)]);OUT<-normalizePath(file.path(dirname(f),'..'))
d<-read.csv(file.path(OUT,'results/TableS6_key_results.csv'),check.names=FALSE,stringsAsFactors=FALSE);w<-createWorkbook(creator='Liu et al.')
addWorksheet(w,'Key results',gridLines=FALSE);writeData(w,'Key results','Table S6. Cross-virus CRRM responses, direct comparisons, and key robustness checks.',startRow=1,colNames=FALSE);mergeCells(w,'Key results',cols=1:ncol(d),rows=1)
writeData(w,'Key results',d,startRow=2,withFilter=TRUE,keepNA=FALSE);freezePane(w,'Key results',firstActiveRow=3,firstActiveCol=6)
title<-createStyle(fontName='Arial',fontSize=12,textDecoration='bold',fontColour='#173E56',wrapText=TRUE,valign='center');addStyle(w,'Key results',title,rows=1,cols=1,gridExpand=TRUE)
head<-createStyle(fontName='Arial',fontSize=10,textDecoration='bold',fontColour='white',fgFill='#173E56',wrapText=TRUE,valign='center');addStyle(w,'Key results',head,rows=2,cols=1:ncol(d),gridExpand=TRUE)
base<-createStyle(fontName='Arial',fontSize=10,wrapText=TRUE,valign='top');addStyle(w,'Key results',base,rows=3:(nrow(d)+2),cols=1:ncol(d),gridExpand=TRUE)
num<-createStyle(numFmt='0.0000');addStyle(w,'Key results',num,rows=3:(nrow(d)+2),cols=8:10,gridExpand=TRUE,stack=TRUE)
pval<-createStyle(numFmt='0.000E+00');addStyle(w,'Key results',pval,rows=3:(nrow(d)+2),cols=11:12,gridExpand=TRUE,stack=TRUE)
setRowHeights(w,'Key results',rows=1,heights=30);setRowHeights(w,'Key results',rows=2,heights=32);setRowHeights(w,'Key results',rows=3:(nrow(d)+2),heights=42)
setColWidths(w,'Key results',cols=1:ncol(d),widths=c(24,23,24,27,29,10,12,13,14,14,14,14,47,64));setHeaderFooter(w,'Key results',footer=c('Liu et al.','Table S6','&P / &N'));pageSetup(w,'Key results',orientation='landscape',fitToWidth=1,fitToHeight=0)
dest<-file.path(OUT,'reports/TableS6_跨病毒比较_crossvirus_r1.xlsx');saveWorkbook(w,dest,overwrite=TRUE);z<-read.xlsx(dest,startRow=2,check.names=FALSE);stopifnot(nrow(z)==nrow(d),ncol(z)==ncol(d));message(dest)
